def transform(grid):
    """Tile 8-cells into 2x2 squares and three oriented L-triomino types."""
    h, w = len(grid), len(grid[0])
    occupied = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}
    # Color 2, 3, and 4 are the three L orientations appearing in the demos.
    templates = {
        1: ((0,0),(0,1),(1,0),(1,1)),
        2: ((0,1),(1,0),(1,1)),
        3: ((0,0),(0,1),(1,1)),
        4: ((0,0),(1,0),(1,1)),
    }
    placements = []
    for color, shape in templates.items():
        for r in range(h - 1):
            for c in range(w - 1):
                cells = frozenset((r + dr, c + dc) for dr, dc in shape)
                if cells <= occupied:
                    placements.append((cells, color))
    by_cell = {p: [] for p in occupied}
    for cells, color in placements:
        for p in cells:
            by_cell[p].append((cells, color))

    def search(left, chosen):
        if not left:
            return chosen
        # Choose the most constrained remaining cell.
        p = min(left, key=lambda q: sum(cells <= left for cells, _ in by_cell[q]))
        for cells, color in by_cell[p]:
            if cells <= left:
                ans = search(left - cells, chosen + [(cells, color)])
                if ans is not None:
                    return ans
        return None

    tiling = search(occupied, [])
    if tiling is None:
        return [row[:] for row in grid]
    out = [[0] * w for _ in range(h)]
    for cells, color in tiling:
        for r, c in cells:
            out[r][c] = color
    return out
